use xiom.io;
use xiom.string;

fn shout(text: Str) -> Str {
  return string.str_upper(text);
}

fn add_exclamation(text: Str) -> Str {
  return string.str_concat(text, "!!!");
}

fn repeat_word(word: Str, times: Int) -> Str {
  var result: Str = "";
  var count: Int = 0;
  while count < times {
    result = string.str_concat(result, word);
    count = count + 1;
  }
  return result;
}

fn main() {
  let headline: Str = "breaking news";
  let loud: Str = shout(headline);
  let louder: Str = add_exclamation(loud);
  io.println(louder);

  let chant: Str = repeat_word("ha", 3);
  io.println(chant);
}
